  { t: "mcq", m: 1, q: "Why are the weak acid assumptions less valid for very dilute solutions?", o: ["Water's contribution to [H<sup>+</sup>] becomes significant", "The acid becomes strong", "K<sub>a</sub> changes", "pH can't be measured"], a: 0 }
